var tokens = (Console.ReadLine() ?? "").Split(' ', StringSplitOptions.RemoveEmptyEntries);
if (tokens.Length != 3) Environment.Exit(1);
if (!int.TryParse(tokens[1], out var price)) Environment.Exit(1);
if (!int.TryParse(tokens[2], out var discount)) Environment.Exit(1);
if (price < 0 || price > 1000000 || discount < 0 || discount > 100) Environment.Exit(1);
var book = new Book(tokens[0], price, discount);
Console.WriteLine(book.GetTitle());
Console.WriteLine(book.PriceAfterDiscount());

class Book
{
    private readonly string _title;
    private readonly int _price;
    private readonly int _discountPercent;

    public Book(string title, int price, int discountPercent)
    {
        _title = title;
        _price = price;
        _discountPercent = discountPercent;
    }

    public string GetTitle() => _title;

    public int PriceAfterDiscount() => _price * (100 - _discountPercent) / 100;
}
